import{z as d,x as i,o as e,c as p,q as o,j as B,D as E,d as r,s as n,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"风险率与生存模型","description":"","frontmatter":{"title":"风险率与生存模型","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hazard-rate-model.md","filePath":"quant/hazard-rate-model.md","lastUpdated":1791063341000}'),A={name:"quant/hazard-rate-model.md"};function m(C,a,D,b,u,h){const l=i("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="风险率与生存模型" tabindex="-1">风险率与生存模型 <a class="header-anchor" href="#风险率与生存模型" aria-label="Permalink to &quot;风险率与生存模型&quot;">​</a></h1><div class="epigraph"><p>别问「一年后违约概率多少」，问「活过今天之后，明天瞬间违约的速率多少」——风险率把信用定价从静态变即时。</p><footer>—— 据 Cox 比例风险模型 (1972)；Duffie–Singleton 信用期限结构框架</footer></div><p><a href="/quant/smile-interpolation">波动率微笑插值</a>解决「期权价格如何跨行权价自洽」，本课转向信用侧的同一类问题：违约时点未知、只能给概率分布，如何定价与对冲。缺口是<strong>风险率（hazard rate）</strong>：条件瞬时违约强度 \\(\\lambda(t)\\)。它和波动率一样是「从市场价格反推的隐含参数」。本课不做违约相关性（copula 那一支）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信用债、CDS 的定价需要「违约何时发生」的完整分布，而市场只给几个期限的 CDS 利差。把违约当作泊松到达，强度 \\(\\lambda\\) 常数化太粗——次贷前后强度差一个量级。缺口：<strong>从离散利差报价反解分段常数的 \\(\\lambda(t)\\)</strong>，即信用曲线 bootstrap。本课不建宏观因子模型。</p><p><span class="marginnote">术语翻译：风险率（hazard rate）= 活到 \\(t\\) 的条件下、\\([t,t+dt]\\) 内违约的概率密度，\\(\\lambda(t)dt=\\Pr(\\tau\\in dt\\,|\\,\\tau\\gt t)\\)；生存概率 \\(S(t)=\\exp(-\\int_0^t\\lambda)\\)。它不是无条件概率密度——条件与无条件差一个「活到今天」。</span></p><p><span class="marginnote">数字实例：常数 \\(\\lambda=2\\%\\)（年化），1 年生存 \\(S(1)=e^{-0.02}\\approx 98.02\\%\\)，1 年无条件违约概率 \\(1-S\\approx 1.98\\%\\)。若回收率 \\(R=40\\%\\)，CDS 公平利差 \\(\\approx(1-R)\\lambda\\approx 120\\) bp——与「利差/损失率」的拇指法则对上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Bootstrap 三步：取市场 CDS 利差 \\(s_1\\lt s_2\\lt s_3\\cdots\\) 按期限排序；假设 \\(\\lambda\\) 在相邻期限间为常数；逐段解方程「CDS 价值 = 0」。CDS 价值 = 保费腿（活着才付）与保护腿（违约时赔 \\(1-R\\)）之差，两腿都按生存概率与贴现因子加权。解出各段 \\(\\lambda\\)，就得到整条信用曲线。</p>',9)),(e(),B(s,null,{default:E(()=>[n(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%B8%82%E5%9C%BA%20CDS%20%E5%88%A9%E5%B7%AE%20s1..sn%22%5D%20--%3E%20B%5B%22%E5%81%87%E8%AE%BE%E5%88%86%E6%AE%B5%E5%B8%B8%E6%95%B0%20%CE%BB%22%5D%0A%20%20B%20--%3E%20C%7B%22%E6%9C%80%E7%9F%AD%E6%9C%9F%3A%20%E8%A7%A3%20%CE%BB1%22%7D%0A%20%20C%20--%3E%20D%5B%22%E5%9B%BA%E5%AE%9A%20%CE%BB1%2C%20%E8%A7%A3%20%CE%BB2%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%80%90%E6%AE%B5%E5%89%8D%E6%8E%A8%E8%87%B3%20%CE%BBn%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%AE%8C%E6%95%B4%E4%BF%A1%E7%94%A8%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%AE%9A%E4%BB%B7%2F%E5%AF%B9%E5%86%B2%E4%BB%BB%E6%84%8F%E5%88%B0%E6%9C%9F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"直觉类比：风险率像「连过几关后下一关的难度系数」。总通关率由各关难度连乘（生存函数取指数），而市场报价只告诉你「通过 1/3/5 年关卡的总概率」——bootstrap 就是逐关反推难度，前面的关先定死，后面的关才轮得到解。")],-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[r("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"Cox 框架下 \\(\\lambda(t)\\) 可以是随机过程（双随机假设：给定强度路径，违约到达是泊松），定价取期望强度即可，这是信用曲线与利率曲线能共用 bootstrap 机器的原因。风险率与违约概率密度的关系 \\(p(t)=\\lambda(t)S(t)\\) 说明：利差陡升未必源于远期违约高，也可能是生存者变少。反解方程里保费腿按季度付、违约时点在期内均匀近似，离散化误差在高利差下显著——机构用期内积分精确处理。",-1)),(e(),B(s,null,{default:E(()=>[n(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E5%88%A9%E5%B7%AE%E5%8F%98%E9%99%A1%E7%9A%84%E5%8E%9F%E5%9B%A0%3F%22%7D%20--%3E%7C%22%CE%BB%20%E4%B8%8A%E5%8D%87%22%7C%20R%5B%22%E8%BF%91%E6%9C%9F%E8%BF%9D%E7%BA%A6%E9%A2%84%E6%9C%9F%E6%81%B6%E5%8C%96%22%5D%0A%20%20Q%20--%3E%7C%22S%20%E4%B8%8B%E9%99%8D%E4%BD%86%20%CE%BB%20%E5%B9%B3%22%7C%20S%5B%22%E5%AD%98%E9%87%8F%E8%BF%9D%E7%BA%A6%E5%85%91%E7%8E%B0%2C%20%E7%BB%93%E6%9E%84%E6%80%A7%E6%8A%AC%E5%8D%87%22%5D%0A%20%20R%20--%3E%20T%5B%22%E4%B9%B0%E4%BF%9D%E6%8A%A4%E5%AF%B9%E5%86%B2%E8%BF%91%E6%9C%9F%22%5D%0A%20%20S%20--%3E%20U%5B%22%E9%87%8D%E4%BC%B0%E7%BB%84%E5%90%88%E4%B9%85%E6%9C%9F%E4%B8%8E%E5%9B%9E%E6%94%B6%22%5D%0A%20%20T%20--%3E%20V%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E6%9B%B2%E7%BA%BF%2C%20%E4%B8%A4%E7%A7%8D%E7%97%85%2C%20%E4%B8%A4%E7%A7%8D%E8%8D%AF%22%5D%0A%20%20U%20--%3E%20V%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：把 CDS 利差直接当违约概率——1000 bp 利差在回收率 40% 下对应 \\(\\lambda\\approx 16.7\\%\\) 而非 10%；又把风险率与年化违约概率混写，忽略 \\(1-e^{-\\lambda}\\) 与 \\(\\lambda\\) 在高 \\(\\lambda\\) 时的差别（\\(\\lambda=30\\%\\) 时两者差 3.5 个百分点）。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型假设违约独立于利率与回收率——真实市场「利差扩大 + 回收下降」同发（wrong-way risk），需引入相关或跳扩散。分段常数假设在报价期限之间插入的是假设不是信息，曲线中段插值方式（平坦 λ 对平坦利差）会让远端定价差几十 bp。数据稀疏时（只有一个 5 年报价）只能先验定形状。与 <a href="/quant/pfe-ee-profile">PFE 敞口曲线</a>的关系：对手方信用曲线是 PFE/CVA 机器的输入之一，风险率错一档，CVA 全线偏移。</p><p><span class="marginnote">直觉类比：利差是「体温」，风险率是「病因曲线」——体温计人人会读，bootstrap 是把体温时间序列翻译成病程；翻译错一截，后面的处方（对冲）全跟着偏。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>风险率 \\(\\lambda(t)\\) 是条件瞬时违约强度；生存函数 \\(S(t)=e^{-\\int\\lambda}\\)。</li><li>CDS 曲线 bootstrap：分段常数 λ，逐段解「CDS 价值为零」。</li><li>利差 ≠ 违约概率：差一个损失率与 \\(1-e^{-\\lambda}\\) 修正。</li><li>出处：Cox (1972)；Duffie–Singleton「Credit Risk」(2003)；ISDA CDS 标准模型。</li></ul>',6))])}const F=d(A,[["render",m]]);export{f as __pageData,F as default};
